#![doc = include_str!("../README.md")]

pub use prpr_macros::{grammar, include_grammar};
pub use prpr_runtime as runtime;
pub use prpr_runtime::{Expected, Found, LineCol, ParseError};

/// Defines a function-like proc-macro that parses its input with a parser generated by prpr, and
/// expands the parsed value with a function. It requires the feature `proc-macro2`.
///
/// ```ignore
/// prpr::define_proc_macro! {
///     /// `calc!(x * (y + 1))`: arithmetic expressions, checked at compile time.
///     calc, grammar::expr, expand
/// }
///
/// fn expand(src: &SourceText, e: Expr) -> Result<proc_macro2::TokenStream, MacroError> {
///     // ...
/// }
/// ```
///
/// The parser, such as the function that a grammar generates for a rule, takes the text of the
/// input and returns the parsed value or a [`ParseError`]. The function takes the
/// [`runtime::SourceText`] of the input and the value, and returns the tokens of the expansion,
/// or a [`runtime::MacroError`] that is reported at the part of the input it is about.
/// Attributes before the name, such as doc comments, are attributes of the proc-macro.
#[cfg(feature = "proc-macro2")]
#[macro_export]
macro_rules! define_proc_macro {
    ($(#[$attr:meta])* $name:ident, $parser:path, $expand:path $(,)?) => {
        $(#[$attr])*
        #[proc_macro]
        pub fn $name(input: ::proc_macro::TokenStream) -> ::proc_macro::TokenStream {
            $crate::runtime::SourceText::with(::core::convert::Into::into(input), |src| {
                let value = $parser(src.text())?;
                $expand(src, value)
            })
            .into()
        }
    };
}

